import * as T from 'three'
import { GLTFLoader } from 'three/addons/loaders/GLTFLoader.js'

// The gameplay root keeps its surface frame; normalization lives below it.
export async function loadSpiderModel(player, url = `${import.meta.env.BASE_URL}models/spider-animated.glb?v=walk-2`) {
  const gltf = await new GLTFLoader().loadAsync(url)
  const visual = new T.Group()
  visual.add(gltf.scene)
  // The supplied spider faces +Z, while the game's forward axis is -Z.
  visual.rotation.y = Math.PI
  const mixer = new T.AnimationMixer(gltf.scene)
  const action = gltf.animations[0] ? mixer.clipAction(gltf.animations[0]) : null
  action?.play()
  mixer.update(0)
  visual.updateMatrixWorld(true)
  const bounds = new T.Box3().setFromObject(visual, true)
  const size = bounds.getSize(new T.Vector3())
  if (!Number.isFinite(size.x) || size.x <= 0) throw new Error('Пустая геометрия паука')
  const scale = 1.55 / Math.max(size.x, size.z)
  gltf.scene.scale.multiplyScalar(scale)
  gltf.scene.position.add(new T.Vector3(-(bounds.min.x+bounds.max.x)/2, -bounds.min.y, -(bounds.min.z+bounds.max.z)/2).multiplyScalar(scale))
  visual.traverse(node => { if (node.isMesh) { node.castShadow = true; node.receiveShadow = true } })
  player.clear()
  player.add(visual)
  attachSpiderAnimation(player, mixer, action, visual, gltf.animations)
  player.userData.model = 'glb'
  return { animation: action?.getClip().name, size: size.toArray() }
}

export function attachSpiderAnimation(player, mixer, action, visual = null, clips = []) {
  if (!action) throw new Error('В модели отсутствует анимация паука')
  action.setLoop(T.LoopRepeat, Infinity).play()
  const gait = Object.fromEntries(['Walk','TurnLeft','TurnRight'].map(name => {
    const clip = clips.find(c => c.name === name)
    const a = clip ? mixer.clipAction(clip).setLoop(T.LoopRepeat, Infinity).play() : null
    a?.setEffectiveWeight(0)
    return [name,a]
  }))
  const separate = Object.values(gait).every(Boolean)
  let pace = .35, lean = 0
  player.userData.updateAnimation = (dt, moving, paused = false, motion = {}) => {
    if (paused || dt <= 0) return
    const turn = T.MathUtils.clamp(motion.turn || 0, -6, 6)
    const speed = moving ? T.MathUtils.clamp(motion.speed ?? 1, 0, 1) : 0
    // Crossfade authored Blender clips; keep the source clip for quiet idle.
    const targetPace = Math.max(.35, speed * 1.6, Math.min(1.45, Math.abs(turn) * .65))
    const blend = 1 - Math.exp(-dt * 10)
    pace = T.MathUtils.lerp(pace, targetPace, blend)
    lean = T.MathUtils.lerp(lean, T.MathUtils.clamp(-turn * .025 - (motion.strafe || 0) * .035, -.09, .09), blend)
    action.timeScale = pace
    if (separate) {
      const turnWeight = Math.min(1, Math.abs(turn) / 1.5)
      const weights = {Walk:speed * (1-turnWeight),TurnLeft:turn>0?turnWeight:0,TurnRight:turn<0?turnWeight:0}
      const idleWeight = 1 - Object.values(weights).reduce((a,b)=>a+b,0)
      action.setEffectiveWeight(T.MathUtils.lerp(action.getEffectiveWeight(),idleWeight,blend))
      for (const [name,a] of Object.entries(gait)) {
        a.setEffectiveWeight(T.MathUtils.lerp(a.getEffectiveWeight(),weights[name],blend))
        a.timeScale = Math.max(.5,pace) * (name === 'Walk' && motion.forward < 0 ? -1 : 1)
      }
    }
    mixer.update(dt)
    // Tilt only the visual child, never the gameplay surface frame or camera.
    if (visual) visual.rotation.z = lean
  }
  player.userData.resetAnimation = () => {
    pace = .35; lean = 0
    if (visual) visual.rotation.z = 0
    for (const a of Object.values(gait)) if (a) a.reset().play().setEffectiveWeight(0)
    action.reset().play().setEffectiveWeight(1); action.timeScale = pace; mixer.update(0)
  }
}

